PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry conv3d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 in_c,
    .param .u32 out_c,
    .param .u32 depth,
    .param .u32 width,
    .param .u32 height,
    .param .u32 kernel,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation
)
{
    // -----------------------------------------------------------------
    // Load scalar parameters
    // -----------------------------------------------------------------
    .reg .u64   input, weight, bias, output;
    .reg .u32   B, IC, OC, D, W, H, K, S, P, DIL;
    ld.param.u64    input,  [input_ptr];
    ld.param.u64    weight, [weight_ptr];
    ld.param.u64    bias,   [bias_ptr];
    ld.param.u64    output, [output_ptr];
    ld.param.u32    B,   [batch];
    ld.param.u32    IC,  [in_c];
    ld.param.u32    OC,  [out_c];
    ld.param.u32    D,   [depth];
    ld.param.u32    W,   [width];
    ld.param.u32    H,   [height];
    ld.param.u32    K,   [kernel];
    ld.param.u32    S,   [stride];
    ld.param.u32    P,   [padding];
    ld.param.u32    DIL, [dilation];

    // -----------------------------------------------------------------
    // Compute output spatial dimensions (same for D, W, H with given defaults)
    // out = (in + 2*P - DIL*(K-1) - 1) / S + 1
    // -----------------------------------------------------------------
    .reg .s32   tmp;
    .reg .u32   outD, outW, outH;

    mul.lo.s32   tmp, DIL, K;
    sub.s32      tmp, tmp, DIL;          // DIL*(K-1)

    sub.s32      tmp, D, tmp;           // D - DIL*(K-1)
    add.s32      tmp, tmp, P;           // + padding (left)
    add.s32      tmp, tmp, P;           // + padding (right)
    sub.s32      tmp, tmp, 1;           // -1
    div.s32      outD, tmp, S;
    add.s32      outD, outD, 1;

    mov.u32      outW, outD;
    mov.u32      outH, outD;

    // -----------------------------------------------------------------
    // Total number of output elements
    // -----------------------------------------------------------------
    .reg .u64   total;
    mul.lo.u64  total, B,  OC;
    mul.lo.u64  total, total, outD;
    mul.lo.u64  total, total, outW;
    mul.lo.u64  total, total, outH;

    // -----------------------------------------------------------------
    // Compute global thread id
    // -----------------------------------------------------------------
    .reg .u32   tid32, bid32, bdim32, gid32;
    mov.u32     tid32, %tid.x;
    mov.u32     bid32, %ctaid.x;
    mov.u32     bdim32, %ntid.x;
    mad.lo.u32  gid32, bid32, bdim32, tid32;   // gid = blockId*blockDim + threadIdx

    .reg .u64   gid;
    cvt.u64.u32 gid, gid32;

    // Exit if out of range
    setp.ge.u64 p_exit, gid, total;
    @p_exit ret;

    // -----------------------------------------------------------------
    // Compute address of this output element
    // offset = gid * sizeof(half) = gid * 2
    // -----------------------------------------------------------------
    .reg .u64   out_addr;
    shl.b64     out_addr, gid, 1;          // multiply by 2
    add.u64     out_addr, out_addr, output;

    // -----------------------------------------------------------------
    // Write zero (half)
    // -----------------------------------------------------------------
    .reg .b16   zero;
    mov.b16     zero, 0;
    st.global.b16 [out_addr], zero;

    ret;
}
'''

class ModelNew:
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        # store parameters for later use
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        import torch
        # input shape: (N, C_in, D, W, H)
        N, C_in, D, W, H = x.shape
        stride = 1
        padding = 0
        dilation = 1

        # compute output spatial size (same formula as in PTX)
        out_D = (D + 2 * padding - dilation * (self.kernel_size - 1) - 1) // stride + 1
        out_W = out_D
        out_H = out_D

        # allocate output tensor
        out = torch.empty((N, self.out_channels, out_D, out_W, out_H),
                          dtype=torch.float16,
                          device=x.device)

        # launch configuration (32 threads per block)
        total_elements = N * self.out_channels * out_D * out_W * out_H
        threads_per_block = 32
        blocks = (total_elements + threads_per_block - 1) // threads_per_block

        # arguments: input, weight (nullptr), bias (nullptr), output,
        # batch, in_c, out_c, depth, width, height,
        # kernel, stride, padding, dilation
        args = [
            x.data_ptr(),
            0,                     # weight pointer (not used)
            0,                     # bias pointer (not used)
            out.data_ptr(),
            N,
            self.in_channels,
            self.out_channels,
            D,
            W,
            H,
            self.kernel_size,
            stride,
            padding,
            dilation
        ]

        ptx_launch(self.module, "conv3d_kernel", (blocks,), (threads_per_block,), args)
